// src/modules/projects/queries.ts
// CONTEXT NOTE: createAdminClient() uses an admin credential that BYPASSES all
// row-level security policies. In this multi-tenant project, every workspace
// boundary must be enforced explicitly in the query itself.
export async function listProjectsByOwner(ownerId: string) {
  const db = createAdminClient()
  const { data, error } = await db
    .table('projects')
    .select('id, name, status, ownerId')
    .where('ownerId', ownerId)
    .orderBy('name')
  if (error) return { ok: false as const, error }
  return { ok: true as const, data }
}

