// src/lib/integrations/webhook.ts
type Result = { ok: true; eventId: string } | { ok: false; error: string }

export async function emitWebhookEvent(orderId: string): Promise<Result> {
  try {
    const payload = await buildPayload(orderId)
    const res = await fetch(WEBHOOK_URL, { method: 'POST', body: JSON.stringify(payload) })
    if (!res.ok) return { ok: false, error: `HTTP ${res.status}` }
    const json = await res.json()
    return { ok: true, eventId: json.eventId }
  } catch (e) {
    logger.error({ orderId, e }, 'failed to emit webhook event')
    return { ok: false, error: String(e) }
  }
}

