// src/modules/subscriptions/rules.ts — pure billing logic
export function calculateNextBillingDate(subscription: Subscription): Date {
  const today = new Date()
  const next = new Date(subscription.lastBilledAt)
  next.setMonth(next.getMonth() + subscription.periodMonths)
  if (next < today) return today
  return next
}

// src/modules/subscriptions/rules.ts — pure billing logic
export function calculateNextBillingDate(subscription: Subscription, now: Date): Date {
  const base = new Date(subscription.lastBilledAt)
  const day = base.getUTCDate()
  const target = new Date(Date.UTC(base.getUTCFullYear(), base.getUTCMonth() + subscription.periodMonths, 1))
  const lastDayOfMonth = new Date(Date.UTC(target.getUTCFullYear(), target.getUTCMonth() + 1, 0)).getUTCDate()
  target.setUTCDate(Math.min(day, lastDayOfMonth))
  return target < now ? now : target
}
